const CACHE='mine-reserve-workbench-v2.0.0';
const FILES=["./manifest.webmanifest", "./app.js", "./ortho_all_new_preview.json", "./base.css", "./ortho_all_new_preview.webp", "./workbench.css", "./index.html", "./workbench.js", "./icons/mark.svg", "./data/Collar_ALL_UKK.csv", "./data/Assay_ALL_UKK.csv", "./data/collar_ukk_d_03122024_new.csv", "./data/collar-tambahan hir.csv", "./data/sources.json", "./data/template.csv", "./data/assay_ukk_d_03122024_NEW__.csv", "./data/assay-hir_04082024.csv", "./data/remain_reserve_okt_hir0.csv", "./data/collar-hir_04082024.csv"];
self.addEventListener('install',e=>e.waitUntil((async()=>{const c=await caches.open(CACHE);for(const f of FILES){const r=await fetch(f,{cache:'reload'});if(!r.ok)throw Error(f);await c.put(f,r);}await self.skipWaiting();})()));
self.addEventListener('activate',e=>e.waitUntil((async()=>{for(const k of await caches.keys())if(k.startsWith('mine-reserve-workbench-')&&k!==CACHE)await caches.delete(k);await self.clients.claim();})()));
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;e.respondWith((async()=>{const c=await caches.open(CACHE);if(e.request.mode==='navigate')return (await c.match('./index.html'))||fetch(e.request);return (await c.match(e.request,{ignoreSearch:true}))||fetch(e.request);})());});
